import java.util.*;

class TokenCache {
    private final Map<String, String> cache = new HashMap<>();
    void put(String user, String token) { cache.put(user, token); }
    String get(String user) { return cache.get(user); }
}

public class AuthModuleDemo {
    static class AuthenticationManager {
        private final TokenCache cache = new TokenCache();
        public void login(String user, String token) {
            cache.put(user, token);
        }
        public String getToken(String user) {
            return cache.get(user);
        }
    }

    public static void main(String[] args) {
        AuthenticationManager auth = new AuthenticationManager();
        auth.login("user1", "tok_abc123");
        System.out.println("Token: " + auth.getToken("user1"));
    }
}

