class PaymentGateway {
    public void pay(double amount) {
        sendHttpPayload(amount);
    }
    protected void sendHttpPayload(double amount) {
        System.out.println("HTTP POST: $" + amount);
    }
}

class MockPaymentGateway extends PaymentGateway {
    @Override
    protected void sendHttpPayload(double amount) {
        System.out.println("MOCK POST: Bypassing network for $" + amount);
    }
}

public class GatewayDemo {
    public static void main(String[] args) {
        PaymentGateway gw = new MockPaymentGateway();
        gw.pay(99.0);
    }
}

