practiceProblems.solution:
import java.util.*;

final class InventoryItem {
    private final String sku;
    private final double price;
    private final List<String> tags;

    public InventoryItem(String sku, double price, List<String> tags) {
        this.sku = sku;
        this.price = price;
        this.tags = (tags != null) ? new ArrayList<>(tags) : new ArrayList<>();
    }

    public String getSku() { return sku; }
    public double getPrice() { return price; }
    public List<String> getTags() { return Collections.unmodifiableList(tags); }
}

public class InventoryDemo {
    public static void main(String[] args) {
        List<String> rawTags = new ArrayList<>(Arrays.asList("Electronics", "Gadget"));
        InventoryItem item = new InventoryItem("SKU-100", 299.99, rawTags);
        rawTags.clear(); // Mutate original list
        System.out.println("Item tags intact: " + item.getTags().size());
    }
}

