practiceProblems.solution:
interface OrderEventListener {
    void onOrderPlaced(String orderId);
}

class UserNotifier implements OrderEventListener {
    public void onOrderPlaced(String orderId) {
        System.out.println("User notified for order: " + orderId);
    }
}

class OrderService {
    private final OrderEventListener listener;
    public OrderService(OrderEventListener listener) {
        this.listener = listener;
    }
    public void placeOrder(String orderId) {
        System.out.println("Order created: " + orderId);
        listener.onOrderPlaced(orderId);
    }
}

public class InversionDemo {
    public static void main(String[] args) {
        OrderEventListener notifier = new UserNotifier();
        OrderService service = new OrderService(notifier);
        service.placeOrder("ORD-990");
    }
}

