    public static boolean canAccessMember(String modifier, boolean sameClass, boolean samePackage, boolean isSubclass) {
        // Full Java spec rules
        return false;
    }

    public static void main(String[] args) {
        System.out.println(canAccessMember("public", false, false, false));
        System.out.println(canAccessMember("protected", false, false, true));
