    }
}

practiceProblems.solution:
public class SpecAccessEvaluator {
    public static boolean canAccessMember(String modifier, boolean sameClass, boolean samePackage, boolean isSubclass) {
        if (sameClass) return true;
        if ("public".equalsIgnoreCase(modifier)) return true;
        if ("private".equalsIgnoreCase(modifier)) return false;
        if (samePackage) return true;
        if ("protected".equalsIgnoreCase(modifier) && isSubclass) return true;
        return false;
    }

    public static void main(String[] args) {
        System.out.println(canAccessMember("public", false, false, false));
        System.out.println(canAccessMember("protected", false, false, true));
        System.out.println(canAccessMember("default", false, false, true));
        System.out.println(canAccessMember("private", false, true, true));
    }
}
